-- 186_replace_decision_21_2021_circular_special_insurance_funds_investment_controls_ocr_corrupted_single_row_with_letterhead_and_footer.sql
--
-- إعادة رفع الكتاب الدورى رقم (21) لسنة 2021 الصادر عن نائب رئيس الهيئة العامة للرقابة المالية بتاريخ 2021/9/7 بشأن ضوابط استثمارات صناديق التأمين الخاصة
-- (المسجَّل فى laws تحت law_no = 21 وlaw_year = 2021 بنوع board_decision، وعنوانه "بشأن ضوابط استثمارات صناديق التأمين الخاصة"): كتاب دورى من فقرتين وتوقيع، بلا ديباجة ولا مواد (فصف واحد بمفتاح article_no = 1، article_suffix_order = 0).
-- لا يوجد "قرار" بالرقم 21 لسنة 2021 هنا: الوثيقة المطبوعة "كتاب دورى" لا قرار، ورابطها الرسمى المسجَّل فى laws هو "الكتاب الدورى رقم 21".
--
-- ===== الحالة السابقة (مراجعة الـ153 وثيقة، أولوية OCR) =====
-- مخزَّن بالبذور صف واحد (article_no = 1، 1519 حرفاً، hierarchical_location = "النص الكامل (وثيقة غير مقسّمة لمواد قانونية مرقّمة)") ناتج عن OCR رديء للصفحة الممسوحة، وبه:
-- (1) رقم الكتاب وتاريخه وسنته مشوهة ("كتاب دوري رقم ( »© ) لسنة 1" و"صادر بتاريخ ٠١71/9/0") فلا يُعرف رقمه ولا تاريخه من النص؛
-- (2) نسبة الاستثمارات الأخرى، وهى جوهر الفقرة الثانية، مشوهة بما لا يُقرأ ("9,05؟" بدل 5%)، وأرقام مواد وقوانين مشوهة (القانون 54 لسنة 1975 والمادتان 27 و35 ومادة اللائحة 14 وقرار الهيئة 99 لسنة 2015)، وسطر كامل من الفقرة الأولى مفقود ("ومنها وضع واعتماد السياسات الاستثمارية للصندوق ومتابعة القنوات الاستثمارية") مما يقطع الجملة؛
-- (3) ترويسة الصفحة المشوهة ("الالار جا س1" و"07/17 100167071") وتذييلها (عنوان القرية الذكية والهاتف والفاكس و"نبنى الجسور لا الحواجز") داخل المتن، وبلا توقيع ولا اسم؛
-- (4) نهايات أسطر CRLF، وتاريخ سريان هو تاريخ تشغيل البذر (2026-10-09) لا تاريخ الكتاب.
-- فلا يصلح النص المخزَّن للاستشهاد الرسمى ولا لإدخاله إلى سياق نموذج اللغة: يفتقد المرجعية (الرقم والتاريخ) والنسبة المقررة (5%).
--
-- ===== المصدر والمنهجية =====
-- PDF من صفحة واحدة (432 كيلوبايت) قدّمه صاحب المشروع؛ هو صورة ممسوحة (198 نقطة للبوصة) على ورق الهيئة وبلا طبقة نص. قُرئ النص من الصورة الأصلية مباشرةً مقاطعَ مكبّرة، وكُبّرت أسطر الأرقام (رقم الكتاب وتاريخه والمواد والقوانين والنسبة) من ضعفين إلى سبعة أضعاف وقُرئت رقماً رقماً.
-- ثم قوبل النص المقروء بمخرجات OCR مستقل (tesseract ara) فلم يظهر فرق فى لفظ غير ضجيج التعرف، سوى سطر كامل أسقطه الـOCR وهو مقروء بصرياً وثابت فى الصورة (السطر الذى يبدأ بـ"الصندوق ومنها وضع واعتماد" فى الفقرة الأولى). والأرقام مصدرها القراءة البصرية المكبّرة لا الـOCR.
-- رقم الكتاب مطبوع بخط الأرقام الهندية "(٢١)" (ويطابق law_no = 21)، وتاريخه "٢٠٢١/٩/٧"؛ النسبة "٥%" بالرقم الهندى والعلامة اللاتينية "%" كما طُبعت؛ ولم يُنقل ختم "مكتب رئيس الهيئة" ورقمه المكتوب بخط اليد (46076) ولا رقم التسجيل اليدوى لأنها ليست من النص.
-- اسم الموقِّع: "المستشار/ رضا عبد المعطى" نائب رئيس مجلس إدارة الهيئة؛ حرف الراء الأول من "رضا" مغطى جزئياً بخط التوقيع اليدوى ويُقرأ "رضا" (ويطابقه ما نُشر من تجديد تعيين المستشار رضا عبد المعطى نائباً لرئيس الهيئة فى مارس 2021)، وأُبقى فى المتن كما طُبع بعد إسقاط الضمة.
-- حُذفت ترويسة الصفحة (شعار "الهيئة العامة للرقابة المالية FINANCIAL REGULATORY AUTHORITY" وسطر "نائب رئيس الهيئة")، وتذييلها (عنوان القرية الذكية والرقم البريدى والهاتف والفاكس وموقع الهيئة وشعار "نبنى الجسور لا الحواجز / Building Bridges not Walls"). وسطر جهة الإصدار وعنوان الكتاب ورقمه وتاريخه فى hierarchical_location للصف.
-- الصف بعنوان "كتاب دوري رقم 21 لسنة 2021"، ومتنه الفقرتان كما طُبعتا (الأولى: تأكيد مسئولية مجلس إدارة الصندوق عن إدارة شئونه ووضع سياسات الاستثمار والالتزام بالقرار 99 لسنة 2015 وحدود المادة 14 من اللائحة دون حاجة لممانعة الهيئة؛ والثانية: وجوب الحصول على عدم ممانعة الهيئة على الاستثمارات الأخرى المقررة بحد أقصى 5% من أموال الصندوق وفق البند 13 من المادة 14) ثم التوقيع كما طُبع فى ثلاثة أسطر ("نائب رئيس مجلس إدارة / الهيئة العامة للرقابة المالية / المستشار/ رضا عبد المعطى").
-- لا تعديل على لفظ المطبوع. أُبقيت كتابته بلا تعديل: "علي" بالياء، و"أقصي" بالياء، و"مسئولية" و"شئون" بالهمزة على النبرة، و"وهى" بالياء، والشرطة " - " قبل "الاستثمارات الأخرى" فى الفقرة الثانية، والفرق فى كتابة "(27) و (35)" بمسافة بعد الواو. كُتب تنوين الفتح على الحرف السابق للألف ("وفقًا" و"حصرًا") بالصيغة المعتمدة فى باقى الهجرات (المطبوع يضعه فوق الألف).
-- الأرقام لاتينية (المطبوعة هندية)، وأُسقطت الضمة وغيرها من علامات التشكيل الصغيرة والتطويل، وضُبطت المسافات حول الفاصلة (" ، ").
--
-- ===== الهيكل =====
-- صف واحد، نسخة واحدة (version_no = 1) بمفتاح (1، 0) هو نفسه المخزَّن؛ فلا تعيد بذور 004/005/006 إدراج الصف القديم (إدراج laws فيها ON CONFLICT DO NOTHING، وإدراج المواد مبنى على RETURNING فلا يعمل مع قانون موجود).
--
-- ===== التاريخ =====
-- effective_from = 2021-09-07: تاريخ إصدار الكتاب المطبوع على الصفحة (معلن). الكتاب بلا بند للعمل به (كتاب دورى توجيهى لا يرد فيه "يعمل به من")، فلم يُفترض يوم بعد الإصدار؛ ويُراجع المراجع القانونى هذا التاريخ. كان القديم تاريخ تشغيل البذر لا تاريخ سريان.
-- ولا تُعدَّل بيانات laws (النوع board_decision والعنوان والتاريخ) فى هذه الهجرة.
--
-- ===== قابلية إعادة التشغيل =====
-- الحذف مشروط بألا تكون الحالة نظيفة (صف واحد بعنوان "كتاب دوري رقم 21 لسنة 2021" ومتنه يبدأ بـ"فى إطار حرص الهيئة")؛ والإدراج ON CONFLICT DO NOTHING. تحقق الختام محصور فى هذا الكتاب ويفشل عند أى انحراف (عدد، أو بقايا تلف،
-- أو محتوى الصف، أو إجمالى الطول 1191 حرفاً).
--
-- ملاحظة تشغيلية: الصف الجديد بلا embedding؛ يلزم scripts/backfill-embeddings.js بعد النشر.
BEGIN;
DO $fix186$
DECLARE
  v_law_id uuid;
  v_n int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 21 AND law_year = 2021 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[186] القرار 21/2021 غير موجود فى laws — تخطّى';
    RETURN;
  END IF;
  IF (SELECT count(*) FROM articles WHERE law_id = v_law_id) = 1
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0 AND title = 'كتاب دوري رقم 21 لسنة 2021' AND body LIKE 'في إطار حرص الهيئة%')
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0) THEN
    RAISE NOTICE '[186] القرار 21/2021 نظيف بالفعل — تخطّى الحذف';
  ELSE
    SELECT count(*) INTO v_n FROM articles WHERE law_id = v_law_id;
    DELETE FROM articles WHERE law_id = v_law_id;
    RAISE NOTICE '[186] أُزيلت % مادة من القرار 21/2021 (نص مخزَّن ملوَّث بأخطاء OCR وتاريخ ورقم مشوهان وترويسة وتذييل الصفحة)', v_n;
  END IF;
END
$fix186$;

WITH ins1_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 1, 0, $h1$الهيئة العامة للرقابة المالية - نائب رئيس الهيئة - كتاب دوري رقم 21 لسنة 2021 صادر بتاريخ 2021/9/7 بشأن ضوابط استثمارات صناديق التأمين الخاصة$h1$, $t1_0$كتاب دوري رقم 21 لسنة 2021$t1_0$, $b1_0$في إطار حرص الهيئة على تنمية وتنويع استثمارات صناديق التأمين الخاصة بما يعود بالنفع على أعضاء تلك الصناديق في ظل المتغيرات المالية الاقتصادية ، وبالإشارة إلى قرار مجلس إدارة الهيئة رقم (99) لسنة 2015 بشأن القواعد والضوابط المنظمة لإدارة محفظة استثمارات صناديق التأمين الخاصة ، فإن الهيئة تؤكد علي مسئولية مجلس إدارة الصندوق وفقًا لأحكام المادة (27) و (35) من القانون 54 لسنة 1975 في إدارة شئون الصندوق ومنها وضع واعتماد السياسات الاستثمارية للصندوق ومتابعة القنوات الاستثمارية المتاحة بالسوق في ظل التطورات الاقتصادية مع الالتزام بالمحددات والضوابط العامة للاستثمار المحددة في القرار سالف الذكر ، وكذا الالتزام بحدود وضوابط توظيف الأموال للصندوق المنصوص عليها في المادة (14) من اللائحة التنفيذية للقانون سالف الذكر وكذا كافة القرارات الصادرة من الهيئة في هذا الشأن ، دون الحاجة للحصول على ممانعة من الهيئة.
أما فيما يخص بأن البند رقم (13) من المادة (14) من اللائحة التنفيذية للقانون المذكور - الاستثمارات الأخرى وهى الاستثمارات بخلاف القنوات الاستثمارية المحددة حصرًا في ذات المادة (14) من اللائحة التنفيذية للقانون والمقررة بحد أقصي 5% من أموال الصندوق فإن الهيئة تؤكد علي ضرورة الحصول علي عدم ممانعة الهيئة عليها.
نائب رئيس مجلس إدارة
الهيئة العامة للرقابة المالية
المستشار/ رضا عبد المعطى$b1_0$
  FROM laws WHERE law_no = 21 AND law_year = 2021 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2021-09-07', 'active' FROM ins1_0;

DO $verify186$
DECLARE
  v_law_id uuid;
  v_n int; v_v int; v_bad int; v_len int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 21 AND law_year = 2021 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[186] القرار 21/2021 غير موجود — لا تحقق';
    RETURN;
  END IF;
  SELECT count(*), COALESCE(sum(length(body)), 0) INTO v_n, v_len FROM articles WHERE law_id = v_law_id;
  IF v_n <> 1 THEN RAISE EXCEPTION '[186] عدد المواد % بدل 1', v_n; END IF;
  SELECT count(*) INTO v_v FROM article_versions av JOIN articles a ON a.id = av.article_id WHERE a.law_id = v_law_id AND av.version_no = 1 AND av.status = 'active' AND av.effective_from = DATE '2021-09-07';
  IF v_v <> 1 THEN RAISE EXCEPTION '[186] عدد النسخ % بدل 1', v_v; END IF;
  SELECT count(*) INTO v_bad FROM articles WHERE law_id = v_law_id AND (body ~ '[٠-٩۰-۹]' OR body ~ '[ٌ-ْ]' OR body LIKE '%' || chr(65533) || '%' OR body LIKE '%ـ%' OR body LIKE '%الالار%' OR body LIKE '%07/17%' OR body LIKE '%نائب رئيس الهيئة ل%' OR body LIKE '%القرية الذكية%' OR body LIKE '%الرقم البريدى%' OR body LIKE '%تليفون%' OR body LIKE '%نبنى الجسور%' OR body LIKE '%Building Bridges%' OR body LIKE '%WWW%' OR body LIKE '%FRA.GOV%' OR body LIKE '%9,05%' OR body LIKE '%٪%' OR body LIKE '%���%' OR body LIKE '%األ%' OR body LIKE '%اإل%' OR body LIKE '%اآل%' OR body LIKE '%ال يقل%' OR body LIKE '%�%');
  IF v_bad > 0 THEN RAISE EXCEPTION '[186] % مادة بها تلف أو بقايا OCR أو ترويسة', v_bad; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0 AND body LIKE 'في إطار حرص الهيئة على تنمية وتنويع استثمارات%' AND body LIKE '%المستشار/ رضا عبد المعطى' AND body LIKE '%قرار مجلس إدارة الهيئة رقم (99) لسنة 2015 بشأن القواعد والضوابط المنظمة%' AND body LIKE '%وفقًا لأحكام المادة (27) و (35) من القانون 54 لسنة 1975%' AND body LIKE '%المادة (14) من اللائحة التنفيذية للقانون سالف الذكر%' AND body LIKE '%دون الحاجة للحصول على ممانعة من الهيئة.%' AND body LIKE '%البند رقم (13) من المادة (14)%' AND body LIKE '%بحد أقصي 5_ من أموال الصندوق%' AND body LIKE '%علي ضرورة الحصول علي عدم ممانعة الهيئة عليها.%' AND body LIKE '%نائب رئيس مجلس إدارة%' AND body LIKE '%المستشار/ رضا عبد المعطى') THEN RAISE EXCEPTION '[186] الكتاب الدورى غير سليم'; END IF;
  IF v_len <> 1191 THEN RAISE EXCEPTION '[186] إجمالى طول المواد % بدل 1191', v_len; END IF;
  RAISE NOTICE '[186] القرار 21/2021: 1 مواد و1 نسخ، إجمالى % حرف', v_len;
END
$verify186$;

COMMIT;
